            $display("Test %0d: IDLE to PROCESSING via start signal", test_num);
            reset_dut();
            @(posedge clk);
            start = 1;
            @(posedge clk);
            #1;
            start = 0;

            #1;


            check_outputs(PROCESSING);
        end
        endtask

