module uart_transmitter (
    input wire clk,
    input wire reset,
    input wire [7:0] data_in,
    input wire data_valid,
    output reg tx,
    output reg busy
);
    parameter BAUD_RATE = 9600;
    parameter CLOCK_FREQ = 50000000; // 50 MHz clock
    localparam BIT_PERIOD = CLOCK_FREQ / BAUD_RATE;

    reg [3:0] state;
    reg [3:0] bit_count;
    reg [15:0] clk_count;

    localparam IDLE = 0, START = 1, DATA = 2, STOP = 3;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            tx <= 1;
            busy <= 0;
            clk_count <= 0;
            bit_count <= 0;
        end else begin
            case (state)
                IDLE: begin
                    tx <= 1; // Idle state
                    busy <= 0;
                    if (data_valid) begin
                        state <= START;
                        clk_count <= 0;
                        bit_count <= 0;
                        busy <= 1;
                    end
                end
                START: begin
                    if (clk_count < BIT_PERIOD) begin
                        clk_count <= clk_count + 1;
                    end else begin
                        clk_count <= 0;
                        tx <= 0; // Start bit
                        state <= DATA;
                    end
                end
                DATA: begin
                    if (clk_count < BIT_PERIOD) begin
                        clk_count <= clk_count + 1;
                    end else begin
                        clk_count <= 0;
                        tx <= data_in[bit_count]; // Send data bits
                        if (bit_count < 7) begin
                            bit_count <= bit_count + 1;
                        end else begin
                            state <= STOP;
                        end
                    end
                end
                STOP: begin
                    if (clk_count < BIT_PERIOD) begin
                        clk_count <= clk_count + 1;
                    end else begin
                        clk_count <= 0;
                        tx <= 1; // Stop bit
                        state <= IDLE;
                    end
                end
            endcase
        end
    end
endmodule

