module deserializer (
    input wire clk,
    input wire reset,
    input wire [31:0] data_in,
    output reg [3:0] data_out,
    output reg done
);
    reg [4:0] count; // 5 bits to count from 0 to 31

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 0;
            data_out <= 0;
            done <= 0;
        end else begin
            if (count < 8) begin
                data_out <= data_in[(count * 4) +: 4];
                count <= count + 1;
                done <= (count == 7) ? 1 : 0; // Set done when the last output is given
            end
        end
    end
endmodule

