module fractional_n_pll (  
    input wire clk_in,  
    input wire rst,  
    input wire [7:0] frac_div,  
    output reg clk_out  
);  
    reg [15:0] counter;  
    reg [7:0] div_counter;  
    reg [7:0] div_value;  
    reg clk_div;  

    always @(posedge clk_in or posedge rst) begin  
        if (rst) begin  
            counter <= 0;  
            div_counter <= 0;  
            clk_out <= 0;  
            div_value <= frac_div;  
        end else begin  
            counter <= counter + 1;  
            if (counter >= div_value) begin  
                clk_div <= ~clk_div;  
                counter <= 0;  
                if (div_counter < div_value) begin  
                    div_counter <= div_counter + 1;  
                end else begin  
                    div_counter <= 0;  
                end  
            end  
            clk_out <= clk_div;  
        end  
    end  
endmodule

