module deserializer (
    input wire clk,
    input wire reset,
    input wire serial_in,
    output reg [15:0] parallel_out
);

    integer count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            parallel_out <= 16'b0;
            count <= 0;
        end else if (count < 16) begin
            parallel_out <= {parallel_out[14:0], serial_in};
            count <= count + 1;
        end
    end
endmodule

