module uart_controller (
    input wire clk,
    input wire reset,
    input wire tx_start,
    input wire [7:0] data_in,
    output reg tx_busy,
    output reg tx_out
);

    reg [3:0] bit_count;
    reg [7:0] shift_reg;
    reg [15:0] baud_rate_counter;
    parameter BAUD_RATE_DIV = 16'd104; // Example for 9600 baud rate at 16MHz clock

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            tx_busy <= 0;
            tx_out <= 1; // idle state of UART is high
            bit_count <= 0;
            baud_rate_counter <= 0;
            shift_reg <= 0;
        end else begin
            if (tx_start && !tx_busy) begin
                tx_busy <= 1;
                shift_reg <= data_in;
                bit_count <= 0;
                baud_rate_counter <= 0;
                tx_out <= 0; // Start bit
            end else if (tx_busy) begin
                if (baud_rate_counter < BAUD_RATE_DIV - 1) begin
                    baud_rate_counter <= baud_rate_counter + 1;
                end else begin
                    baud_rate_counter <= 0;
                    if (bit_count < 8) begin
                        tx_out <= shift_reg[bit_count]; // Send data bits
                        bit_count <= bit_count + 1;
                    end else begin
                        tx_out <= 1; // Stop bit
                        tx_busy <= 0; // Transmission complete
                    end
                end
            end
        end
    end
endmodule

