module vco (  
    input wire [3:0] control_voltage,  
    input wire clk,  
    input wire reset,  
    output reg out  
);  

    reg [31:0] counter;  
    reg [31:0] frequency;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            out <= 0;  
            frequency <= 1;  
        end else begin  
            frequency <= frequency * 2;  
            counter <= counter + 1;  
            if (counter >= (100000000 / frequency)) begin  
                out <= ~out;  
                counter <= 0;  
            end  
        end  
    end  
endmodule

