module uart_transmitter (
    input wire clk,
    input wire rst,
    input wire send,
    input wire [7:0] data_in,
    output reg tx,
    output reg ready
);
    parameter BAUD_RATE = 9600;
    parameter CLOCK_FREQ = 50000000; // 50 MHz
    localparam CLOCK_COUNT = CLOCK_FREQ / BAUD_RATE;

    reg [3:0] bit_index;
    reg [11:0] clock_counter;
    reg sending;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tx <= 1; // Idle state is high
            ready <= 1;
            bit_index <= 0;
            clock_counter <= 0;
            sending <= 0;
        end else if (send && ready) begin
            sending <= 1;
            ready <= 0;
            bit_index <= 0;
            clock_counter <= 0;
        end else if (sending) begin
            if (clock_counter < CLOCK_COUNT - 1) begin
                clock_counter <= clock_counter + 1;
            end else begin
                clock_counter <= 0;
                if (bit_index < 10) begin
                    case (bit_index)
                        0: tx <= 0; // Start bit
                        1: tx <= data_in[0];
                        2: tx <= data_in[1];
                        3: tx <= data_in[2];
                        4: tx <= data_in[3];
                        5: tx <= data_in[4];
                        6: tx <= data_in[5];
                        7: tx <= data_in[6];
                        8: tx <= data_in[7];
                        9: tx <= 1; // Stop bit
                    endcase
                    bit_index <= bit_index + 1;
                end else begin
                    sending <= 0;
                    ready <= 1; // Ready for the next transmission
                end
            end
        end
    end
endmodule

